Description: This Terraform configuration creates a private 2-node Amazon Redshift cluster in `us-east-1`. It provisions a dedicated VPC, two private subnets, a Redshift subnet group, and a security group. It also configures a Redshift usage limit that restricts concurrency scaling usage to 60 minutes per day.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "redshift_cluster_identifier" {
  description = "Identifier for the Redshift cluster."
  type        = string
  default     = "example-redshift-cluster"
}

